// src/components/NewDeploymentForm.js
import React, { useState, useEffect } from 'react';

const NewDeploymentForm = ({ setShowForm, setDeploymentInfo }) => {
  const [title, setTitle] = useState('');
  const [sourceOrg, setSourceOrg] = useState('');
  const [targetOrg, setTargetOrg] = useState('');
  const [orgs, setOrgs] = useState([]);

  useEffect(() => {
    const storedOrgs = JSON.parse(localStorage.getItem('organizations')) || [];
    setOrgs(storedOrgs);
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (sourceOrg === targetOrg) {
      alert('Source and Target organizations cannot be the same.');
      return;
    }
    const deployment = { title, sourceOrg, targetOrg };
    setDeploymentInfo(deployment);
    localStorage.setItem('deploymentInfo', JSON.stringify(deployment));
    setShowForm(false);
  };

  return (
    <div>
      <h2>New Deployment</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="title">Title</label>
          <input
            type="text"
            id="title"
            name="title"
            placeholder="change summary ..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
        </div>
        <div>
          <label htmlFor="sourceOrg">Source Org</label>
          <select
            id="sourceOrg"
            name="sourceOrg"
            value={sourceOrg}
            onChange={(e) => setSourceOrg(e.target.value)}
          >
            <option value="">select</option>
            {orgs.map((org, index) => (
              <option key={index} value={org.name}>{org.name}</option>
            ))}
          </select>
        </div>
        <div>
          <label htmlFor="targetOrg">Target Org</label>
          <select
            id="targetOrg"
            name="targetOrg"
            value={targetOrg}
            onChange={(e) => setTargetOrg(e.target.value)}
          >
            <option value="">select</option>
            {orgs.map((org, index) => (
              <option key={index} value={org.name}>{org.name}</option>
            ))}
          </select>
        </div>
        <button type="submit">Save</button>
        <button type="button" onClick={() => setShowForm(false)}>Cancel</button>
      </form>
    </div>
  );
};

export default NewDeploymentForm;
